Running command: cd /workspace && cat > test_poc.c << 'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Copy the relevant declarations from lwan.h and lwan-private.h */
struct lwan_value {
    char *value;
    size_t len;
};

enum lwan_connection_flags {
    CONN_IS_UPGRADE = 1,
    CONN_FLIP_FLAGS = 2,
    CONN_IS_WEBSOCKET = 4,
};

struct lwan_connection {
    enum lwan_connection_flags flags;
    unsigned int time_to_die;
    struct coro *coro;
    struct lwan_thread *thread;
    int prev, next;
};

/* Just enough to compile and link */
#include "/workspace/repo-vul/src-vul/lwan/src/lib/lwan.h"
#include "/workspace/repo-vul/src-vul/lwan/src/lib/lwan-private.h"

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long len = ftell(f);
    fseek(f, 0, SEEK_SET);

    if (len > 32767) len = 32767;

    /* This is the fuzz target */
    extern int fuzz_parse_http_request(const uint8_t *data, size_t length);

    uint8_t *data = malloc(len);
    fread(data, 1, len, f);
    fclose(f);

    int ret = fuzz_parse_http_request(data, len);
    free(data);
    return ret;
}
EOF
echo "done"

